PROGRAM MixCell

(* SFC Generated from Visual Editor *)

VAR
    (* Step Active Flags *)
    X_step_idle : BOOL := TRUE; (* Step: IDLE *)
    X_step_fill : BOOL := FALSE; (* Step: FILL *)
    X_step_heat : BOOL := FALSE; (* Step: HEAT *)
    X_step_fill_done : BOOL := FALSE; (* Step: FILL_DONE *)
    X_step_heat_done : BOOL := FALSE; (* Step: HEAT_DONE *)
    X_step_mix : BOOL := FALSE; (* Step: MIX *)

    (* Step Elapsed Timers *)
    T_step_idle : TON; (* Timer for IDLE *)
    T_step_fill : TON; (* Timer for FILL *)
    T_step_heat : TON; (* Timer for HEAT *)
    T_step_fill_done : TON; (* Timer for FILL_DONE *)
    T_step_heat_done : TON; (* Timer for HEAT_DONE *)
    T_step_mix : TON; (* Timer for MIX *)

    (* Transitions That Fire In This Scan *)
    _F_t_start : BOOL;
    _F_t_fill_done : BOOL;
    _F_t_heat_done : BOOL;
    _F_t_join : BOOL;
    _F_t_mix_done : BOOL;
    (* Transition Conditions, as They Were Evaluated In This Scan *)
    _C_t_start : BOOL;
    _C_t_fill_done : BOOL;
    _C_t_heat_done : BOOL;
    _C_t_join : BOOL;
    _C_t_mix_done : BOOL;

END_VAR

VAR_INPUT
    Start AT %I0.0 : BOOL; (* Start pushbutton *)
END_VAR

VAR_OUTPUT
    Valve AT %Q0.0 : BOOL; (* Fill valve *)
    Heater AT %Q0.1 : BOOL; (* Heater *)
    Mixer AT %Q0.2 : BOOL; (* Mixer motor *)
END_VAR

(* === Step Timers === *)
T_step_idle(IN := X_step_idle, PT := T#24h);
T_step_fill(IN := X_step_fill, PT := T#24h);
T_step_heat(IN := X_step_heat, PT := T#24h);
T_step_fill_done(IN := X_step_fill_done, PT := T#24h);
T_step_heat_done(IN := X_step_heat_done, PT := T#24h);
T_step_mix(IN := X_step_mix, PT := T#24h);

(* === Action Execution === *)
(* Action: A_IDLE *)
IF X_step_idle THEN
    Valve := FALSE; Heater := FALSE; Mixer := FALSE;
END_IF;

(* Action: A_FILL *)
IF X_step_fill THEN
    Valve := TRUE;
END_IF;

(* Action: A_HEAT *)
IF X_step_heat THEN
    Heater := TRUE;
END_IF;

(* Action: A_FILL_DONE *)
IF X_step_fill_done THEN
    Valve := FALSE;
END_IF;

(* Action: A_HEAT_DONE *)
IF X_step_heat_done THEN
    Heater := FALSE;
END_IF;

(* Action: A_MIX *)
IF X_step_mix THEN
    Mixer := TRUE;
END_IF;

(* === Transition Logic === *)
(* Transition: IDLE -> FILL & HEAT (Both branches start together) *)
_C_t_start := (Start);
_F_t_start := X_step_idle AND _C_t_start;
(* Transition: FILL -> FILL_DONE *)
_C_t_fill_done := (T_step_fill.ET >= T#30ms);
_F_t_fill_done := X_step_fill AND _C_t_fill_done;
(* Transition: HEAT -> HEAT_DONE *)
_C_t_heat_done := (T_step_heat.ET >= T#50ms);
_F_t_heat_done := X_step_heat AND _C_t_heat_done;
(* Transition: FILL_DONE & HEAT_DONE -> MIX (Wait for both branches) *)
_C_t_join := (TRUE);
_F_t_join := X_step_fill_done AND X_step_heat_done AND _C_t_join;
(* Transition: MIX -> IDLE *)
_C_t_mix_done := (T_step_mix.ET >= T#30ms);
_F_t_mix_done := X_step_mix AND _C_t_mix_done;

IF _F_t_start THEN X_step_idle := FALSE; END_IF;
IF _F_t_fill_done THEN X_step_fill := FALSE; END_IF;
IF _F_t_heat_done THEN X_step_heat := FALSE; END_IF;
IF _F_t_join THEN X_step_fill_done := FALSE; END_IF;
IF _F_t_join THEN X_step_heat_done := FALSE; END_IF;
IF _F_t_mix_done THEN X_step_mix := FALSE; END_IF;
IF _F_t_start THEN X_step_fill := TRUE; END_IF;
IF _F_t_start THEN X_step_heat := TRUE; END_IF;
IF _F_t_fill_done THEN X_step_fill_done := TRUE; END_IF;
IF _F_t_heat_done THEN X_step_heat_done := TRUE; END_IF;
IF _F_t_join THEN X_step_mix := TRUE; END_IF;
IF _F_t_mix_done THEN X_step_idle := TRUE; END_IF;

END_PROGRAM

